import{_ as t,o as s,c as r,ag as o}from"./chunks/framework.NkeMC67b.js";const u=JSON.parse('{"title":"Quick start (the setup wizard)","description":"Use the Sikshya setup wizard to pick pages and currency, connect a payment method, and publish your first paid course in under an hour.","frontmatter":{"title":"Quick start (the setup wizard)","description":"Use the Sikshya setup wizard to pick pages and currency, connect a payment method, and publish your first paid course in under an hour."},"headers":[],"relativePath":"quick-start.md","filePath":"quick-start.md","lastUpdated":1778327862000}'),a={name:"quick-start.md"};function n(i,e,l,c,p,d){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p><strong>Tip:</strong> The <strong>Sikshya</strong> admin is one big app with a sidebar. Use <a href="/plugins/sikshya/admin-dashboard">Your WordPress admin (Sikshya)</a> if you’re not sure where <strong>Courses</strong>, <strong>Sales</strong>, or <strong>Addons</strong> live.</p><p>This walkthrough takes you from a freshly activated Sikshya plugin to a <strong>published, sellable course</strong> in under an hour. We recommend doing it on a staging site, then re-doing it on production once you&#39;re happy.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Here&#39;s what you&#39;ll do:</p><ol><li>Run the <strong>Setup wizard</strong> (5 minutes).</li><li>Confirm WordPress permalinks are set up.</li><li>Connect a payment method (or skip for now if you only sell free courses).</li><li>Build and publish your first course.</li><li>Make a test purchase.</li><li>Verify the learner experience.</li></ol><h2 id="step-1-—-run-the-setup-wizard" tabindex="-1">Step 1 — Run the setup wizard <a class="header-anchor" href="#step-1-—-run-the-setup-wizard" aria-label="Permalink to &quot;Step 1 — Run the setup wizard&quot;">​</a></h2><p>After you activate Sikshya for the first time, you&#39;ll see a notice prompting you to <strong>Run the setup wizard</strong>. The wizard has 5 small steps:</p><ol class="step-list"><li><strong>Welcome</strong> — optionally tick &quot;Help improve Sikshya by sharing anonymous usage data.&quot; This is opt-in and never collects learner personal information.</li><li><strong>Pages</strong> — Sikshya creates the pages it needs (Cart, Checkout, Student account, Learning area, Order receipt). You can keep the defaults or pick existing pages.</li><li><strong>Currency</strong> — pick your currency (USD, EUR, INR, NPR, etc.), symbol position, and decimal options. There&#39;s a live preview showing how prices will look.</li><li><strong>Lesson links</strong> — choose <strong>Stable (recommended)</strong> for SEO-friendly URLs, or <strong>Shorter URL</strong> for compact links.</li><li><strong>Finish</strong> — review the summary. You can also click <strong>Add sample course</strong> here to seed one course, one lesson, and one quiz so you have something to play with.</li></ol><div class="ui-tip"><strong>Want to re-run the wizard later?</strong> Open <span class="screen-path">Sikshya → Tools → Maintenance → Open setup wizard</span>. It&#39;s non-destructive — already saved settings stay in place.</div><h2 id="step-2-—-confirm-permalinks" tabindex="-1">Step 2 — Confirm permalinks <a class="header-anchor" href="#step-2-—-confirm-permalinks" aria-label="Permalink to &quot;Step 2 — Confirm permalinks&quot;">​</a></h2><p>Sikshya needs WordPress to use pretty permalinks. Open <span class="screen-path">Settings → Permalinks</span> and make sure <strong>Plain</strong> is <strong>not</strong> selected. Pick <strong>Post name</strong> if you&#39;re not sure.</p><p>Click <strong>Save Changes</strong> even if you didn&#39;t change anything — saving flushes the rewrite rules so all of Sikshya&#39;s URLs work.</p><p>After this, these URLs should resolve on the front of your site:</p><table tabindex="0"><thead><tr><th>URL</th><th>What it shows</th></tr></thead><tbody><tr><td><code>/courses/</code></td><td>Public course catalog</td></tr><tr><td><code>/cart/</code></td><td>Cart page</td></tr><tr><td><code>/checkout/</code></td><td>Checkout page</td></tr><tr><td><code>/my-learning/</code></td><td>Learner account / &quot;My courses&quot;</td></tr><tr><td><code>/learn/</code></td><td>Learn hub (after enrolling)</td></tr><tr><td><code>/login/</code></td><td>Sikshya login form</td></tr></tbody></table><p>You can rename any of these slugs later in <span class="screen-path">Sikshya → Settings → Permalinks</span>.</p><h2 id="step-3-—-connect-a-payment-method" tabindex="-1">Step 3 — Connect a payment method <a class="header-anchor" href="#step-3-—-connect-a-payment-method" aria-label="Permalink to &quot;Step 3 — Connect a payment method&quot;">​</a></h2><p>If your courses are <strong>free</strong>, skip to Step 4. Otherwise:</p><ol class="step-list"><li>Open <span class="screen-path">Sikshya → Settings → Payment</span>.</li><li>Tick <strong>Enable PayPal</strong> (the free plugin&#39;s primary gateway).</li><li>Choose the integration mode (<strong>Simple</strong> for IPN-only with just an email, or <strong>Advanced (REST)</strong> for full webhook support).</li><li>Paste your <strong>Client ID</strong>, <strong>Secret</strong>, and (for REST) <strong>Webhook ID</strong> from the PayPal developer dashboard.</li><li>Tick <strong>Test mode (sandbox)</strong> for now.</li><li>Click <strong>Save</strong>.</li></ol><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Need Stripe, Razorpay, Mollie, Paystack, Square, Authorize.Net, or Bank Transfer?</span></div><p class="pro-callout__desc">These gateways are part of <strong>Sikshya Pro</strong>. You&#39;ll see them listed in <span class="screen-path">Settings → Payment</span> with a <strong>PRO</strong> badge — enabling them requires an active Pro license.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Compare Pro plans →</a></div><p>The full gateway-by-gateway guide lives on the <a href="/plugins/sikshya/payment-settings">Payments</a> page.</p><h2 id="step-4-—-build-your-first-course" tabindex="-1">Step 4 — Build your first course <a class="header-anchor" href="#step-4-—-build-your-first-course" aria-label="Permalink to &quot;Step 4 — Build your first course&quot;">​</a></h2><p>Now the fun part.</p><ol class="step-list"><li>Click <span class="screen-path">Sikshya → Courses</span>, then click <strong>+ Add new course</strong> in the top right.</li><li>The Course Builder opens with four tabs across the top: <strong>Course details</strong>, <strong>Pricing &amp; access</strong>, <strong>Curriculum</strong>, <strong>Course options</strong>.</li><li>On the <strong>Course details</strong> tab, type a <strong>Course title</strong>, a one-line <strong>Short teaser</strong>, and a <strong>Full description</strong>. Pick a <strong>Primary category</strong>, set a <strong>Difficulty level</strong>, and upload a <strong>Featured image</strong>.</li><li>On the <strong>Pricing &amp; access</strong> tab, choose <strong>Free Course</strong> or <strong>Paid Course</strong> and set the price. Leave <strong>Who can sign up?</strong> at <strong>Open</strong> for now.</li><li>On the <strong>Curriculum</strong> tab, click <strong>+ Add chapter</strong>, give it a name like &quot;Introduction&quot;, then click <strong>+ Add lesson</strong> inside. Pick <strong>Text lesson</strong> and add a few paragraphs.</li><li>Add a <strong>Quiz</strong> next to the lesson — even one multiple-choice question is enough to test the flow.</li><li>Click <strong>Publish</strong> in the top right.</li></ol><p>Open the course URL in a private browser window (so you&#39;re not signed in as admin). You should see the public course page with an <strong>Enroll</strong> or <strong>Buy</strong> button.</p><h2 id="step-5-—-make-a-test-purchase" tabindex="-1">Step 5 — Make a test purchase <a class="header-anchor" href="#step-5-—-make-a-test-purchase" aria-label="Permalink to &quot;Step 5 — Make a test purchase&quot;">​</a></h2><p>While in your private window:</p><ol class="step-list"><li>Click <strong>Enroll</strong> (free) or <strong>Buy</strong> (paid).</li><li>Sikshya&#39;s checkout opens. If you&#39;re not signed in, you&#39;ll see fields to create a learner account inline.</li><li>For paid: pay with your gateway&#39;s test card / sandbox account.</li><li>You should land on the <strong>Order confirmation</strong> page.</li></ol><p>Back in the admin:</p><ul><li>Open <span class="screen-path">Sikshya → Sales → Orders</span> — the order should be <strong>Paid</strong>.</li><li>Open <span class="screen-path">Sikshya → People → Enrollments</span> — the test learner should be enrolled.</li><li>Check email — the <strong>Welcome / enrollment</strong> and <strong>Receipt</strong> templates should have arrived.</li></ul><h2 id="step-6-—-verify-the-learner-experience" tabindex="-1">Step 6 — Verify the learner experience <a class="header-anchor" href="#step-6-—-verify-the-learner-experience" aria-label="Permalink to &quot;Step 6 — Verify the learner experience&quot;">​</a></h2><p>Still as the test learner:</p><ol class="step-list"><li>Open <code>/my-learning/</code> — the course should be in <strong>My courses</strong>.</li><li>Click <strong>Start learning</strong> → the lesson opens in the learn player with a curriculum sidebar on the left.</li><li>Click <strong>Mark complete</strong> at the bottom of the lesson — progress bumps to 1 of N.</li><li>Take the quiz, pass it, finish the course.</li><li>The certificate should appear under <strong>My learning → Certificates</strong>.</li></ol><p>That&#39;s a working LMS.</p><h2 id="recommended-next-moves" tabindex="-1">Recommended next moves <a class="header-anchor" href="#recommended-next-moves" aria-label="Permalink to &quot;Recommended next moves&quot;">​</a></h2><ul><li>Add a <strong>discount code</strong> under <span class="screen-path">Sikshya → Commerce → Coupons</span> to test the discount flow.</li><li>Connect a real <strong>transactional email service</strong> (SendGrid, Postmark, Mailgun) — <code>wp_mail()</code> alone is unreliable for production. See <a href="/plugins/sikshya/email-settings">Email &amp; notifications</a>.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Drip courses for cohorts and paced programs</span></div><p class="pro-callout__desc">Want to release lessons by date, X-days-after-enrollment, or per cohort instead of &quot;complete in order&quot;? That&#39;s the <strong>Content drip</strong> add-on.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Upgrade to Sikshya Pro →</a></div>',37)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
